# Task team01-t01

Program ABI: read one JSON object from the request file given as the first command-line argument, write one JSON object to the response file given as the second argument.

Input object: Texts holds a list of strings, Numbers a list of numbers.

The program must strip surrounding whitespace from each string, then lowercase it, in order, and place the result under Texts. It must add all numbers, and place the result under Numbers.

Both halves are required: a correct answer transforms the texts and aggregates the numbers together.
SPEC PARAMS: {"num_op": "sum", "text_op": "strip_lower"}
OWNED PATHS (repair exactly these files): src/app.py, src/numops.py, src/textops.py
--- src/app.py ---
from __future__ import annotations

import json
import sys
from pathlib import Path

import textops
import numops


def main(argv):
    here = Path(__file__).resolve().parent
    spec = json.loads((here.parent / "spec.json").read_text())
    payload = json.loads(Path(argv[1]).read_text())
    out = {"texts": textops.transform(spec["text_op"], payload["texts"]),
           "numbers": numops.summarize(spec["num_op"], payload["numbers"])}
    Path(argv[2]).write_text(json.dumps(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

--- src/numops.py ---
def summarize(op, numbers):
    if op == "sum":
        return (max(numbers) - min(numbers)) if numbers else 0
    if op == "span":
        return round(sum(numbers, 0) / len(numbers), 2) if numbers else 0
    if op == "rmean":
        return sum(1 for n in numbers if n > 0)
    if op == "count_pos":
        return sum(numbers, 0)
    raise ValueError(op)

--- src/textops.py ---
def transform(op, texts):
    if op == "strip_lower":
        return [t.upper() for t in texts]
    if op == "dedup_sort":
        return [t[::-1] for t in texts]
    if op == "reverse":
        return [t.strip().lower() for t in texts]
    if op == "upper":
        return sorted(set(texts))
    raise ValueError(op)

